def verify_isbn(isbn: str) -> str:
    parts = isbn.split('-')
    if len(parts) != 4:
        return isbn
    digits_str = ''.join(parts)
    if len(digits_str) != 10:
        return isbn
    digits = []
    for ch in digits_str:
        if ch == 'X':
            digits.append(10)
        else:
            digits.append(int(ch))
    total = sum((i + 1) * digits[i] for i in range(10))
    if total % 11 == 0:
        return "Right"
    sum9 = sum((i + 1) * digits[i] for i in range(9))
    correct_last = (-sum9 * 10) % 11
    correct_last_char = 'X' if correct_last == 10 else str(correct_last)
    parts[3] = correct_last_char
    return '-'.join(parts)

def count_passing_ways(n: int, m: int) -> int:
    if m == 0:
        return 1
    dp = [0] * n
    dp[0] = 1
    for _ in range(m):
        new = [0] * n
        for i in range(n):
            new[i] = dp[(i - 1) % n] + dp[(i + 1) % n]
        dp = new
    return dp[0]

