def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    terms = []
    first = True
    for i, coeff in enumerate(coeffs):
        degree = n - i
        if coeff == 0:
            continue
        sign = ''
        if first:
            if coeff < 0:
                sign = '-'
        else:
            sign = '+' if coeff > 0 else '-'
        abs_coeff = abs(coeff)
        coeff_str = ''
        if abs_coeff != 1 or degree == 0:
            coeff_str = str(abs_coeff)
        var_str = ''
        if degree > 0:
            var_str = 'x' + (f'^{degree}' if degree > 1 else '')
        term = f"{sign}{coeff_str}{var_str}"
        terms.append(term)
        first = False
    if not terms:
        return '0'
    return ''.join(terms)

def decode(encoded: str, original: str, message: str) -> str:
    if len(encoded) != len(original):
        return "Failed"
    mapping = {}
    for e, o in zip(encoded, original):
        if e in mapping:
            if mapping[e] != o:
                return "Failed"
        else:
            mapping[e] = o
    if len(mapping) != 26 or len(set(mapping.values())) != 26:
        return "Failed"
    try:
        return ''.join(mapping[c] for c in message)
    except KeyError:
        return "Failed"

def largest_prime_factor(n: int) -> int:
    i = 2
    while i * i <= n:
        if n % i == 0:
            return n // i
        i += 1
    return n

def count_sequences(n: int, last: int, memo: dict) -> int:
    if last in memo:
        return memo[last]
    if last <= 1:
        memo[last] = 1
        return 1
    total = 1  # count the sequence that ends at 'last'
    max_next = last // 2
    for k in range(1, max_next + 1):
        total += count_sequences(n, k, memo)
    memo[last] = total
    return total

def count_coprime_pairs(x0: int, y0: int) -> int:
    if x0 <= 0 or y0 <= 0:
        return 0
    if y0 % x0 != 0:
        return 0
    n = y0 // x0

    def _gcd(a: int, b: int) -> int:
        while b:
            a, b = b, a % b
        return a

    count = 0
    limit = int(n**0.5)
    for a in range(1, limit + 1):
        if n % a == 0:
            b = n // a
            if _gcd(a, b) == 1:
                if a == b:
                    count += 1
                else:
                    count += 2
    return count

def string_transformation(A: str, B: str, rules: list) -> Union[int, str]:
    from collections import deque
    if A == B:
        return 0
    max_steps = 10
    visited = {A}
    queue = deque([(A, 0)])
    while queue:
        current, steps = queue.popleft()
        if steps >= max_steps:
            continue
        for src, tgt in rules:
            start = 0
            while True:
                idx = current.find(src, start)
                if idx == -1:
                    break
                new_str = current[:idx] + tgt + current[idx + len(src):]
                if new_str == B:
                    return steps + 1
                if new_str not in visited:
                    visited.add(new_str)
                    queue.append((new_str, steps + 1))
                start = idx + 1
    return "NO ANSWER!"

def is_prime(num: int) -> bool:
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def generate_numbers(n, rules) -> int:
    from collections import deque
    start = str(n)
    visited = {start}
    queue = deque([start])
    while queue:
        current = queue.popleft()
        for i, ch in enumerate(current):
            digit = int(ch)
            for x, y in rules:
                if digit == x:
                    new_num = current[:i] + str(y) + current[i+1:]
                    if new_num not in visited:
                        visited.add(new_num)
                        queue.append(new_num)
    return len(visited)

def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    """
    Evaluates the consistency of a scenario where one participant is the criminal based on the given statements.
    """
    # Helper to determine truth of a statement
    def is_truth(statement: str, speaker: str) -> bool:
        # Ignore statements about days of the week
        for day in days_of_week:
            if day in statement:
                return None  # indicate to ignore
        # Normalize statement
        stmt = statement.strip().rstrip('.').strip()
        # Handle "I am guilty." / "I am not guilty."
        if stmt.lower() == "i am guilty":
            return scenario == speaker
        if stmt.lower() == "i am not guilty":
            return scenario != speaker
        # Handle "<NAME> is guilty." / "<NAME> is not guilty."
        parts = stmt.split()
        if len(parts) == 3 and parts[1].lower() == "is":
            target = parts[0]
            if parts[2].lower() == "guilty":
                return scenario == target
            if parts[2].lower() == "not":
                # Expect "not guilty" as two words
                return scenario != target
        # Handle "<NAME> is not guilty."
        if len(parts) == 4 and parts[1].lower() == "is" and parts[2].lower() == "not" and parts[3].lower() == "guilty":
            target = parts[0]
            return scenario != target
        # If statement format not recognized, treat as neutral (ignore)
        return None

    for speaker, stmts in statements.items():
        is_liar = speaker in liar_count
        for stmt in stmts:
            truth_val = is_truth(stmt, speaker)
            if truth_val is None:
                continue  # ignore
            if is_liar and truth_val:
                return False  # liar said true
            if not is_liar and not truth_val:
                return False  # truth-teller said false
    return True

