def minimum_students_to_leave(heights):
    n = len(heights)
    if n <= 1:
        return 0
    lis = [1] * n
    for i in range(n):
        for j in range(i):
            if heights[j] < heights[i] and lis[j] + 1 > lis[i]:
                lis[i] = lis[j] + 1
    lds = [1] * n
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            if heights[j] < heights[i] and lds[j] + 1 > lds[i]:
                lds[i] = lds[j] + 1
    max_len = 0
    for i in range(n):
        cur = lis[i] + lds[i] - 1
        if cur > max_len:
            max_len = cur
    return n - max_len
